import{_ as p,a0 as a,w as i,s as l,ao as u,I as r,x as e,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"10个在随机出现在面试中的Linux问题及答案 | LCTT x X-CMD","titleTemplate":false,"description":"10个在随机出现在面试中的Linux问题及答案 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10个在随机出现在面试中的Linux问题及答案 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10个在随机出现在面试中的Linux问题及答案 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/10 Useful Random Linux Interview Questions and Answers_t","title":"10个在随机出现在面试中的Linux问题及答案","tag":"201404","desc":""},"relativePath":"201404/10 Useful Random Linux Interview Questions and Answers_t.md","filePath":"[post].md"}'),d={name:"201404/10 Useful Random Linux Interview Questions and Answers_t.md"};function c(m,t,g,w,f,h){const n=a("Link");return i(),l("div",null,[t[11]||(t[11]=u(`<h1 id="_10个在随机出现在面试中的linux问题及答案" tabindex="-1">10个在随机出现在面试中的Linux问题及答案 <a class="header-anchor" href="#_10个在随机出现在面试中的linux问题及答案" aria-label="Permalink to “10个在随机出现在面试中的Linux问题及答案”">​</a></h1><p>为了给你们带来一些小惊喜，这次我们准备了一些在面试中随机出现的问题而不是专门关于某个领域的问题。这些问题肯定会在不深入学习新知识的前提下使你在面试中脱颖而出。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Random-Interview-Questions.png" alt=""></p><p>1.假设你在为你工作的公司维护一份日常的备份。这份备份是以压缩后的格式而被维护着。现在你需要检查一份两个月之前的日志，你应该提出什么样的建议从而可以在不解压这份备份的前提下完成检查日志的任务？</p><blockquote><p><strong>答案</strong>： 在不解压文件的前提下检查文件内容，我们需要用到&#39;zcat&#39;。zcat这个工具可以轻松完成这个任务。</p></blockquote><pre><code># zcat ­f phpshell­2.4.tar.gz
</code></pre><p>2.你需要追踪你系统中发生的事件，你应该怎么做？</p><blockquote><p><strong>答案</strong>： 为了追踪系统中发生的事件，我们需要用到叫做syslogd的这个后台程序。syslogd这个后台程序可以追踪系统信息并将其保存到指定的日志文件中。</p></blockquote><p>启用&#39;syslogd&#39;这个后台进程会在路径&#39;/var/log/syslog&#39;中生成一个日志文件。syslogd应用对解决Linux系统中的问题十分有用。标准生成的日志文件和下面这个例子很像。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/syslongd.jpg" alt="syslogd"></p><p>3.如何禁止特定IP访问FTP服务器？</p><blockquote><p><strong>答案</strong>： 我们可以通过运用tcp_wrapper来禁止可疑的IP访问。首先在路径&#39;/etc/vsftpd.conf&#39;的配置文件中，将tcp_wrapper这个参数设置为&quot;tcp_wrapper=YES&quot;，然后在&#39;/etc/host.deny&#39;文件中加入可疑的IP地址。</p></blockquote><p><strong>禁止访问的IP地址</strong></p><p>打开&#39;/etc/hosts.deny&#39;文件。</p><pre><code># vi /etc/hosts.deny
</code></pre><p>在文件底端加入拒绝访问的IP地址</p><pre><code>#
# hosts.deny    This file contains access rules which are used to
#               deny connections to network services that either use
#               the tcp_wrappers library or that have been
#               started through a tcp_wrappers-enabled xinetd.
#
#               The rules in this file can also be set up in
#               /etc/hosts.allow with a &#39;deny&#39; option instead.
#
#               See &#39;man 5 hosts_options&#39; and &#39;man 5 hosts_access&#39;
#               for information on rule syntax.
#               See &#39;man tcpd&#39; for information on tcp_wrappers
#
vsftpd:172.16.16.1
</code></pre><p>4.告诉我们Telnet和SSH之间的区别？</p><blockquote><p><strong>答案</strong>： Telnet和SSH都是用来远程管理系统的协议。与Telnet直接传输数据正好相反，安全的SSH通信协议需要通信中有密钥的交换，这说明telnet相比较于SSH不安全。</p></blockquote><p>5.你需要终止你的X server，但当你尝试杀进程的时候，你遇到了表示不能退出X server的错误信息。你准备怎么做？</p><blockquote><p><strong>答案</strong>： 当你尝试杀X server的进程时，系统不会让你像使用&#39;/etc/init.d/gdm stop&#39;一样正常的退出X server。我们需要执行一个使X server重启的特别的键位组合&#39;Ctrl+ Alt+ BackSpace&#39;。</p></blockquote><p>6.告诉我命令&#39;ping&#39;和&#39;ping6&#39;的区别？</p><blockquote><p><strong>答案</strong>： 这两个命令有同样的功能，但&#39;ping6&#39;命令可被用于ipv6的IP地址。</p></blockquote><p>7.你想要在Home目录下寻找*.tar文件并一次性删除，你会怎么做？</p><blockquote><p><strong>答案</strong>： 我们要同时用到find和rm命令来删除所有*.tar文件</p></blockquote><pre><code># find /home/ ­name &#39;*.tar&#39; | xargs rm ­rf
</code></pre><p>8.locate和slocate命令的区别？</p><blockquote><p><strong>答案</strong>： slocate(secure locate)会寻找所有用户有权限访问的文件，然而locate会搜索（它的数据库里面的）所有更新过的结果。</p></blockquote><p>9.你要在当前目录中所有“.txt”文件中搜索“Tecmint”这个字符串，你怎么做？</p><blockquote><p><strong>答案</strong>： 用find命令在当前目录递归寻找文件中的“Tecmint”字符串。</p></blockquote><pre><code># find ­name “*.txt” | xargs grep “Tecmint”
</code></pre><p>10.你要向所有已连接的用户发送“Server is going down for maintenance”这样一条信息，你怎么做？</p><blockquote><p><strong>答案</strong>： 运用wall命令就可以很容易地实现，wall命令可以向所有已连接服务器的用户发送信息。</p></blockquote><pre><code># echo please save your work, immediately. The server is going down for Maintenance at 12:30 Pm, sharply. | wall
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/wall.jpg" alt="wall command"></p><hr>`,36)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/useful-random-linux-interview-questions-and-answers/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.tecmint.com/useful-random-linux-interview-questions-and-answers/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：ThomazL(",-1)),o(n,{href:"https://github.com/ThomazL"},{default:s(()=>[...t[2]||(t[2]=[e("https://github.com/ThomazL",-1)])]),_:1}),t[5]||(t[5]=e(") 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const k=p(d,[["render",c]]);export{b as __pageData,k as default};
